import json, collections, re
W = '/tmp/claude-501/oracle/work/'
tot = collections.Counter()
ex = collections.defaultdict(list)
for n in ['mantine', 'chakra', 'shadcn', 'antd', 'spectrum']:
    for r in json.load(open(W + n + '.dump.json')):
        if r['verdict'] != 'less precise' or not any('prim where checker has literal' in x for x in r['reasons']):
            continue
        c = r['caliper']
        ms = c['members'] if c['kind'] == 'union' else [c]
        kinds = {m['kind'] for m in ms}
        ck = r['checker']
        cs = ('& {}' in ck) or re.search(r'\b(string|number)\b', ck) is not None
        key = (n, 'caliper has string/number' if kinds & {'string', 'number'} else 'no prim', 'checker mentions prim' if cs else 'no prim in checker')
        tot[key] += 1
        ex[key].append((json.dumps(c)[:160], ck[:120], r['reasons']))
for k, v in sorted(tot.items()):
    print(k, v)
for k in ex:
    if 'no prim' in k[1] or 'no prim in' in k[2]:
        print(k, ex[k][:3])

